CHD_st.name='CHD'; 
CHD_st.lat=30.74;
CHD_st.lon=76.79;
CHD_st.alt=0000;
CHD_st.env='Con';
CHD_st.footp='U';
%%
% data imported via the import tool from matlab

CHD_rd_h.Properties.DimensionNames{1}='Time';
CHD_rd_h.Properties.VariableNames{2}='Ba1_A';
CHD_rd_h.Properties.VariableNames{3}='Ba2_A';
CHD_rd_h.Properties.VariableNames{4}='Ba3_A';
CHD_rd_h.Properties.VariableNames{5}='Ba4_A';
CHD_rd_h.Properties.VariableNames{6}='Ba5_A';
CHD_rd_h.Properties.VariableNames{7}='Ba6_A';
CHD_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(CHD_rd_h);
%%
CHD_rd=retime(CHD_rd_h,'daily',@nanmedian);
%%
datevec(CHD_rd.Time(1)) % begin in 2016,  %[output:470b6a3b]
datevec(CHD_rd.Time(end)) % end in 2019  %[output:5331b040]
plotFigControl(CHD_rd,CHD_st.name); %--> absorption is presently too short %[output:2f6cd29c]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
CHD_cal=compute_exp_D(CHD_rd,names_abs,lambdaAE7); %[output:36960dfa] %[output:3cd4cd00] %[output:8c3400e7] %[output:00abacf4]
plotFigControl_cal(CHD_cal,CHD_st.name); %[output:637f3c13] %[output:71baf685] %[output:2afe983f]
%%
%HOMOGENEITY

break_CHD_abs_BP=change_point_analysis_Def(CHD_rd,names_abs,0.05,'CHD','Absorption'); %[output:1091ea41] %[output:2d465c34] %[output:1f5bd31f] %[output:81e3143e] %[output:61fbfbc3] %[output:2c0b7310]
T_CHD_abs_BP=make_table_breakpoints_def(break_CHD_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:1bda24dc]
break_CHD_expA_BP=change_point_analysis_Def(CHD_cal,names_expA,0.05,'CHD','Absorption exponent'); %[output:0a625657] %[output:6dc6abca] %[output:77654654] %[output:89620bea]
T_CHD_expA_BP=make_table_breakpoints_def(break_CHD_expA_BP);


